/*
 * A045296  Numbers whose base-5 representation contains exactly one 3 and no
 *          4's.
 * https://oeis.org/A045296
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   Generated by enumerating base‑5 numbers that contain exactly one
 *            digit 3 and no digit 4
 * Range:     u8 n <= 53, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* Recursive helper: builds numbers of exact length `len`. */
static void build_len(size_t pos, size_t len, seq_t val, uint8_t count3,
                      seq_t **arr, size_t *sz, size_t *cap)
{
    if (pos == len) {
        if (count3 == 1) {
            if (*sz == *cap) {
                size_t newcap = (*cap > 0) ? (*cap << 1) : 64;
                seq_t *tmp = (seq_t *)realloc(*arr, newcap * sizeof(seq_t));
                *arr = tmp;
                *cap = newcap;
            }
            (*arr)[*sz] = val;
            ++(*sz);
        }
        return;
    }

    int start = (pos == 0) ? 1 : 0;          /* first digit cannot be 0 */
    for (int d = start; d <= 3; ++d) {       /* digits 0..3 only, no 4 */
        uint8_t nc = count3 + (d == 3);
        if (nc > 1) continue;
        build_len(pos + 1, len, val * ((seq_t)5) + (seq_t)d,
                  nc, arr, sz, cap);
    }
}

/* Append all numbers of length `len` to the global cache. */
static void generate_len(size_t len, seq_t **arr, size_t *sz, size_t *cap)
{
    build_len(0, len, (seq_t)0, 0, arr, sz, cap);
}

/* Function required by the test harness. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                  /* undefined, defensive */
    static seq_t *cache = NULL;
    static size_t cache_size = 0;
    static size_t cache_cap   = 0;
    static size_t last_len_generated = 0;

    /* Ensure cache has at least n entries. */
    while (cache_size < (size_t)n) {
        ++last_len_generated;
        generate_len(last_len_generated, &cache, &cache_size, &cache_cap);
    }
    return cache[(size_t)(n - 1)];
}
